    /// <summary>Binary-searches a sorted, non-overlapping range table for the value covering <paramref name="codepoint"/>, or <paramref name="fallback"/> if none does.</summary>
    private static TValue Lookup<TValue>((int Start, int End, TValue Value)[] ranges, int codepoint, TValue fallback)
    {
        var lo = 0;
        var hi = ranges.Length - 1;
        while (lo <= hi)
        {
            var mid = lo + (hi - lo) / 2;
            var (start, end, value) = ranges[mid];
            if (codepoint < start) { hi = mid - 1; }
            else if (codepoint > end) { lo = mid + 1; }
            else { return value; }
        }

        return fallback;
    }

    /// <summary>The Unicode <c>Script</c> property of <paramref name="codepoint"/>; <see cref="UnicodeScript.Unknown"/> if unassigned/unlisted.</summary>
    public static UnicodeScript GetScript(int codepoint) => Lookup(ScriptRanges, codepoint, UnicodeScript.Unknown);

    /// <summary>The Unicode <c>Joining_Type</c> of <paramref name="codepoint"/>; <see cref="JoiningType.U"/> (Non_Joining) if unlisted — Unicode's own default for characters outside the cursive-joining scripts.</summary>
    public static JoiningType GetJoiningType(int codepoint) => Lookup(JoiningTypeRanges, codepoint, JoiningType.U);

    /// <summary>The Unicode <c>Joining_Group</c> of <paramref name="codepoint"/>; <see cref="JoiningGroup.No_Joining_Group"/> if unlisted.</summary>
    public static JoiningGroup GetJoiningGroup(int codepoint) => Lookup(JoiningGroupRanges, codepoint, JoiningGroup.No_Joining_Group);

    /// <summary>The Unicode <c>Indic_Syllabic_Category</c> of <paramref name="codepoint"/>; <see cref="IndicSyllabicCategory.Other"/> if unlisted.</summary>
    public static IndicSyllabicCategory GetIndicSyllabicCategory(int codepoint) => Lookup(IndicSyllabicCategoryRanges, codepoint, IndicSyllabicCategory.Other);

    /// <summary>The Unicode <c>Indic_Positional_Category</c> of <paramref name="codepoint"/>; <see cref="IndicPositionalCategory.NA"/> if unlisted.</summary>
    public static IndicPositionalCategory GetIndicPositionalCategory(int codepoint) => Lookup(IndicPositionalCategoryRanges, codepoint, IndicPositionalCategory.NA);

    /// <summary>The Unicode <c>Bidi_Class</c> of <paramref name="codepoint"/> (UAX #9) — the source data is fully default-expanded, so every codepoint in 0..10FFFF resolves to a real value.</summary>
    public static BidiClass GetBidiClass(int codepoint) => Lookup(BidiClassRanges, codepoint, BidiClass.L);

    /// <summary>The Unicode Canonical_Combining_Class of <paramref name="codepoint"/>; 0 (not reordered) if unlisted, matching UAX #9/UAX #15's default.</summary>
    public static byte GetCombiningClass(int codepoint) => Lookup(CombiningClassRanges, codepoint, (byte)0);

    /// <summary>The Unicode <c>Grapheme_Cluster_Break</c> of <paramref name="codepoint"/> (UAX #29); <see cref="GraphemeClusterBreak.Other"/> if unlisted.</summary>
    public static GraphemeClusterBreak GetGraphemeClusterBreak(int codepoint) => Lookup(GraphemeClusterBreakRanges, codepoint, GraphemeClusterBreak.Other);

    /// <summary>Unicode <c>Bidi_Mirroring_Glyph</c> (UAX #9 L4): the mirrored codepoint to substitute when <paramref name="codepoint"/> is drawn in a right-to-left run, or <see langword="false"/> if it has none.</summary>
    public static bool TryGetBidiMirror(int codepoint, out int mirror)
    {
        var lo = 0;
        var hi = BidiMirrorPairs.Length - 1;
        while (lo <= hi)
        {
            var mid = lo + (hi - lo) / 2;
            var (pairCodepoint, pairMirror) = BidiMirrorPairs[mid];
            if (codepoint < pairCodepoint) { hi = mid - 1; }
            else if (codepoint > pairCodepoint) { lo = mid + 1; }
            else { mirror = pairMirror; return true; }
        }

        mirror = 0;
        return false;
    }
